static void handle_byte(char ch, char *buffer, size_t *length) {
	if ((unsigned char)ch == 6) {
		write_response("P");
		return;
	}
	if (ch == ':' || ch == '>') {
		*length = 0;
		return;
	}
	if (ch == '#') {
		buffer[*length] = 0;
		handle_command(buffer);
		*length = 0;
		return;
	}
	if (*length + 1 < 128) {
		buffer[(*length)++] = ch;
	}
}

int main(int argc, char *argv[]) {
	if (!parse_args(argc, argv)) {
		return 2;
	}

	char port[PATH_MAX];
	serial_fd = serial_simulator_open_pty(port, sizeof(port));
	if (serial_fd < 0) {
		return 1;
	}
	if (options.ready_file != NULL && !serial_simulator_write_ready_file(options.ready_file, simulator_name, port)) {
		close(serial_fd);
		return 1;
	}
	if (!options.headless) {
		printf("LX200 mount simulator ready on %s\n", port);
	}

	signal(SIGINT, signal_handler);
	signal(SIGTERM, signal_handler);

	char command[128] = { 0 };
	size_t command_length = 0;
	while (running) {
		fd_set readfds;
		FD_ZERO(&readfds);
		FD_SET(serial_fd, &readfds);
		struct timeval timeout = { 0, 100000 };
		int selected = select(serial_fd + 1, &readfds, NULL, NULL, &timeout);
		if (selected < 0) {
			if (errno == EINTR) {
				continue;
			}
			break;
		}
		if (selected == 0 || !FD_ISSET(serial_fd, &readfds)) {
			continue;
		}
		char buffer[64];
		ssize_t count = read(serial_fd, buffer, sizeof(buffer));
		if (count > 0) {
			for (ssize_t i = 0; i < count; i++) {
				handle_byte(buffer[i], command, &command_length);
			}
		} else if (count < 0 && (errno == EINTR || errno == EAGAIN || errno == EWOULDBLOCK || errno == EIO)) {
			usleep(1000);
		} else if (count == 0) {
			usleep(1000);
		} else {
			break;
		}
	}
	if (serial_fd >= 0) {
		close(serial_fd);
	}
	return 0;
}
